mapper.select:
SELECT l.*, s.knowledge_domain
FROM ai_chat_log l
LEFT JOIN ai_chat_session s ON s.id = l.session_id
WHERE 1 = 1

    AND l.user_id = #{queryUserId}


    AND l.user_id = #{userId}


    AND (l.question LIKE CONCAT('%', #{keyword}, '%')
         OR l.answer LIKE CONCAT('%', #{keyword}, '%'))


    AND s.knowledge_domain = #{knowledgeDomain}


    AND l.hit_flag = #{hitFlag}

ORDER BY l.created_at DESC
LIMIT #{size} OFFSET #{offset}
